import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.7F0gE-aX.js";const u=JSON.parse('{"title":"Development and documentation","description":"","frontmatter":{},"headers":[],"relativePath":"development/contributing.md","filePath":"development/contributing.md","lastUpdated":null}'),o={name:"development/contributing.md"};function n(d,e,r,l,c,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="Development-and-documentation" tabindex="-1">Development and documentation <a class="header-anchor" href="#Development-and-documentation" aria-label="Permalink to &quot;Development and documentation {#Development-and-documentation}&quot;">​</a></h1><p>Activate the repository root for package work. Keep the documentation environment separate so tutorial-only dependencies do not become runtime dependencies.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate(); Pkg.test()&#39;</span></span></code></pre></div><p><code>Pkg.test()</code> activates test extras, including OptimizationOptimJL. Running <code>test/runtests.jl</code> directly from the root environment does not activate those extras.</p><h2 id="Build-the-site" tabindex="-1">Build the site <a class="header-anchor" href="#Build-the-site" aria-label="Permalink to &quot;Build the site {#Build-the-site}&quot;">​</a></h2><p>From the repository root, set up the docs environment once:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.develop(path=pwd()); Pkg.instantiate()&#39;</span></span></code></pre></div><p>Install Node.js 20 or newer with npm, then build and preview:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/make.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>The build executes Markdown examples and doctests, checks exported docstrings, generates Markdown, runs <code>npm ci</code>, and builds VitePress. It does not deploy by default. <code>DOCS_DEPLOY=true</code> enables deployment and is set only in the documentation workflow; Documenter also checks the GitHub event before publishing.</p><p>For live editing, run these commands from the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>The transmon–resonator tutorial is generated with Literate.jl from <code>docs/src/tutorials/transmon_resonator_control.jl</code>. Edit its prose in <code>#</code> comments and its Julia code directly in that file; the build generates the Markdown page and executes its code blocks. Do not edit the generated <code>docs/src/tutorials/transmon_resonator_control.md</code>.</p><p><code>docs:dev</code> watches <code>docs/src</code> and regenerates Markdown in Documenter&#39;s draft mode before refreshing the browser. Julia formats the documentation, but examples and doctests do not execute; calculated outputs and plots are omitted. Save a source file and allow generation to finish before expecting the update. Stop with Ctrl+C. From inside <code>docs/</code>, use <code>npm run docs:dev</code> instead.</p><p>To serve the last generated docs without regeneration, use <code>npm --prefix docs run docs:serve</code>. This watches <code>docs/build/.documenter</code> only. Run the full Julia build above when you need updated example results or docstrings from package source. <code>DOCS_MARKDOWN_ONLY=true</code> skips the website build but still executes examples unless you also set <code>DOCS_DRAFT=true</code>.</p><h2 id="Source-organization" tabindex="-1">Source organization <a class="header-anchor" href="#Source-organization" aria-label="Permalink to &quot;Source organization {#Source-organization}&quot;">​</a></h2><p>Keep explicit overloads in <code>overloads.jl</code> beside the structures they extend. <code>src/time_evolution</code> owns solver-based evolution; generic fidelity metrics live in <code>src/utils/metrics/fidelities.jl</code>, and gate-specific metrics live in <code>src/gates/utils/metrics.jl</code>. Hamiltonians use frequency units; apply <code>2π</code> at solver calls rather than constructors or <code>numerical</code>.</p><h2 id="Adding-documentation" tabindex="-1">Adding documentation <a class="header-anchor" href="#Adding-documentation" aria-label="Permalink to &quot;Adding documentation {#Adding-documentation}&quot;">​</a></h2><ul><li><p>Add API docstrings next to their definitions, including units and return values.</p></li><li><p>Render each supported API in one reference <code>@docs</code> block. Build coverage is strict.</p></li><li><p>Put runnable tutorial code in named <code>@example</code> blocks. Use assertions for expected behavior and small deterministic models.</p></li><li><p>Keep output plots and temporary bundles in the build or temporary directories.</p></li><li><p>Add pages to the navigation in <code>docs/make.jl</code>.</p></li><li><p>Run the production build, package tests for source changes, and <code>git diff --check</code>.</p></li></ul><p>CI builds pull requests and deploys the <code>dev</code> branch and version tags to <code>gh-pages</code>. Every valid version tag appears in the version picker, including prereleases. The npm lockfile is committed so site dependencies are reproducible.</p><h2 id="Release-workflow" tabindex="-1">Release workflow <a class="header-anchor" href="#Release-workflow" aria-label="Permalink to &quot;Release workflow {#Release-workflow}&quot;">​</a></h2><p>Ongoing work happens on <code>dev</code>; <code>main</code> records released commits. To publish a release, merge the validated <code>dev</code> work into <code>main</code>, set <code>Project.toml</code> to the release version, and run the package tests and docs build. Tag that exact <code>main</code> commit with <code>v</code> followed by the project version (for example, <code>v0.1.0-alpha.1</code>), push the tag, and create a GitHub Release. Mark alpha and beta releases as prereleases. The tag build publishes its own docs, while <code>dev</code> continues to publish at <code>/dev/</code>. After release, advance <code>dev</code> to the next development version.</p><p>Docs watcher verification marker 20261008.</p>`,23)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
